body:
{
  "pains": [
    {
      "id": "pain:crawls-when-it-grows",
      "statement": "Notion gets slower the more we actually put in it, and the databases we live in every day are the ones that crawl.",
      "element": "b2b:functional:scalability",
      "shape": {
        "surface": "A database that was instant with ten rows takes seconds to open once it has a few hundred, and the mobile app is worse than the desktop one.",
        "operational": "People split and archive their own databases to keep the working copy fast, stop trusting the app for anything time-sensitive, and eventually export the whole thing to Obsidian or move task tracking to Linear.",
        "personal": "The cost lands at the exact moment they cannot wait: standing in a shop with the list not loading, or losing the thread of a sentence while a tab spins and a prompt for an AI feature appears on top of it."
      },
      "workflow": "Opening a Notion database of a few hundred rows in the desktop app or a browser tab, and opening the Notion mobile app at the point of use - in a shop checking a shopping list, or on a phone between meetings, where an accidental tap while scrolling edits the page.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The database crosses a few hundred items, which is roughly where base698 says it stopped being usable.",
          "cites": ["src:1"]
        },
        {
          "event": "Someone on the team tries a file-based or native alternative and reports back how fast it is by comparison.",
          "cites": ["src:2", "src:3"]
        }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "Notion was unusable after more than a few hundred items in a DB.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Opening a note in a tab take 10 seconds and interrupts me half the time with some random news or a prompt to try some AI feature.",
              "cites": ["src:5"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "When i'm out and about checking my shopping list, I have a tolerance for maybe 250ms of lag. That's it. You need to show me my data FAST.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "I migrated from Notion to Obsidian, mainly because of speed",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Seconds on every open, repeated dozens of times a day, plus the re-logins and the mis-taps that come with a web app on a phone; lucw puts his own tolerance at 250ms and Notion is nowhere near it.",
          "fears": "That the workspace he has put years into is the thing making him slow, and that it only gets worse as he adds more, so the longer he stays the more expensive leaving becomes.",
          "dream_outcome": "The note is on screen the instant he taps, on the phone, with no login and no chance of editing it by accident."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "There are a lot I dont like about Notion. Mostly on performance.",
              "cites": ["src:6"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I've resorted to duplicating each database and archiving anything that is worth keeping. That way databases I use operationally retain speed.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "She is running a manual archiving routine to keep her own tool quick, which is unpaid maintenance work she took on because the product would not do it; ksec is absorbing the same complaint on behalf of a team that will not move.",
          "fears": "That she recommended this to everyone and now owns both the complaints and the workaround, and that the day she cannot keep it fast is the day the team stops using it.",
          "dream_outcome": "One database that stays fast as it grows, so there is nothing to duplicate, archive or apologise for."
        }
      },
      "segments": ["seg:individual", "seg:startup"],
      "feature_ref": null,
      "feature_note": "No feature in the company artifact addresses this; it is a property of the product rather than a gap a feature fills. It is in this map because it is the single most repeated reason people in these threads give for leaving, which makes it an objection the positioning step has to answer rather than a promise the offer step can make.",
      "cites": ["src:1", "src:2", "src:3", "src:5"]
    },
    {
      "id": "pain:offline-blackout",
      "statement": "If I don't have signal I can't get at my own notes, and I never know which of my changes will still be there when I'm back.",
      "element": "b2b:ease_of_doing_business:availability",
      "shape": {
        "surface": "The app opens on a page that will not load, or loads a cached copy and silently withholds changes until the connection returns.",
        "operational": "People keep a second tool for anything they might need on a plane, back the workspace up somewhere else through the API, or move out entirely to something file-based that syncs through iCloud or Syncthing.",
        "personal": null,
        "personal_note": "No source read here shows what it costs the person. The offline complaints stop at the missing capability and the decision to leave over it; nobody describes the meeting, the flight or the deadline where it actually cost them something. Looked through the Notion Calendar, Notion AI waitlist, Notion API, Linear Mobile, Evernote, Obsidian and Docs threads on Hacker News and the one- and two-star Trustpilot reviews. q:pains-offline-moment asks the founder for the real one."
      },
      "workflow": "Opening the Notion desktop or mobile app on a plane, a train, or a bad hotel connection, at the step where a page that is not already cached will not render - and at the step after, where edits made offline do not appear until the connection comes back.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A Notion outage: the service was inaccessible for close to 24 hours in May 2021 and had a multi-hour incident in October 2023, both of which sent people looking for backups.",
          "cites": ["src:41", "src:42"]
        },
        {
          "event": "Evaluating an offline-first alternative - Obsidian, Anytype, Linear - which puts the gap in front of them in one sentence.",
          "cites": ["src:7"]
        }
      ],
      "who_feels": ["end_user", "blocker"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Still no offline-mode? Notion is a really great tool, but I really want my data local to tinker with them in all kind of ways which Notion was not made to support.",
              "cites": ["src:10"]
            },
            {
              "situation": "when_looking",
              "verbatim": "The only copy of my data should not exist solely in an app's cloud, and I should not need to manually export anything.",
              "cites": ["src:9"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "If you try to use Notion off-line, it randomly won't show you changes until you're back online.",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "A second tool to maintain, a backup routine to remember, and the small ongoing tax of not knowing whether what is on screen is current.",
          "fears": "That the only copy of years of his own writing lives on somebody else's server and he has no way to hold it himself.",
          "dream_outcome": "The whole workspace is on his machine, works with no connection, and syncs when there is one."
        },
        "blocker": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "My notes are not useful if I can only get to them when I have internet.",
              "cites": ["src:43"]
            },
            {
              "situation": "venting",
              "verbatim": "Notion doesn't have offline support, mobile exports don't work last I tried, no printing or sharing.",
              "cites": ["src:43"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Without this \"feature\" I will never use Notion. Offline mode is a minimum for me to even look at such an information handling product.",
              "cites": ["src:8"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "i used to use Notion, but the lack of offline mode, even after all these years, made me decide to look for alternatives.",
              "cites": ["src:7"]
            }
          ],
          "costs_them": "Nothing yet in most cases, because he has not bought; the cost is borne by whoever wanted to bring Notion in and now has to argue past a stated minimum. vorpalhex has turned it into a written requirement list, which is the form this objection takes when it reaches a evaluation.",
          "fears": "That a tool holding the team's information can be taken away by a bad connection or a bad afternoon at the vendor, and that he will be the one who approved it.",
          "dream_outcome": "Offline as a stated guarantee rather than a roadmap item, so the question does not have to be asked again."
        }
      },
      "segments": ["seg:individual", "seg:startup"],
      "feature_ref": null,
      "feature_note": "No feature in the company artifact answers this. dunham, who looked at the protocol, says the blockers are that the client does not hold a full copy of the data and that some operations including search run server-side, so this is architectural rather than a missing toggle. What would kill it is a local-first client; today the honest answer is the API export auslegung points to, which is a backup and not offline working.",
      "cites": ["src:7", "src:8", "src:9", "src:10", "src:26", "src:27", "src:43"]
    },
    {
      "id": "pain:wiki-where-information-goes-to-die",
      "statement": "Everything is in the wiki and I still can't find the one page I need, so I give up and go ask a person.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "Search returns the wrong pages or nothing useful, and gets worse with every page added, so people navigate by clicking down the sidebar tree instead of searching.",
        "operational": "They stop using search, drill through the page hierarchy, or interrupt a colleague in chat; and somebody quietly inherits the job of reorganising the tree so the drilling still works.",
        "personal": "Whoever ends up curating it gets nothing for it. hnlmorg's line is the whole personal rung: organising docs is an endless and thankless job which nobody wants to do."
      },
      "workflow": "Typing into Notion's search box, or the picker that opens on @-mention, to find a page in a workspace with hundreds of pages - then abandoning it and clicking down the sidebar; and the same step in Confluence six months after the page was written.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The workspace keeps growing: koliber says search gets less useful with each additional page, so the trigger is simply another month of use.",
          "cites": ["src:14"]
        },
        {
          "event": "New people join and start docs on whichever platform they already like, which splits the place the answer might be.",
          "cites": ["src:16"]
        }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I'm eagerly waiting for the day that I don't get frustrated with Notion's search. I'm not sure if I actually even bother with the search that much these days. I just try to drill down the page structure to find what looks relevant.",
              "cites": ["src:15"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "Try writing documentation in confluence and you'll get why Notion is preferable. Also go try to find something you wrote in confluence six months ago.",
              "cites": ["src:17"]
            }
          ],
          "costs_them": "The minutes per lookup are the small part; the real cost is that he has stopped expecting search to work at all and now navigates a tree by memory.",
          "fears": "That the answer is in there somewhere and he will act without it, or ask a question that makes him look like he did not check.",
          "dream_outcome": "He types the thing he half-remembers and the right page is the first result, in a workspace this size and the next one."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Companies often don't suffer from a lack of documentation, but from poorly organized, maintained, and curated documentation. The problem is finding what you are looking for.",
              "cites": ["src:13"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Both search from the \"search button\" and the search that pops up when I type \"@bla\" are becoming less useful with each additional page in my workspace.",
              "cites": ["src:14"]
            },
            {
              "situation": "venting",
              "verbatim": "You also have to bear in mind that organising docs is an endless and thankless job which nobody wants to do.",
              "cites": ["src:16"]
            }
          ],
          "costs_them": "Unpaid curation work on top of her actual job, and the steady erosion of the case she made for putting everything in one place.",
          "fears": "That the wiki she championed becomes the place information goes to die, and that the next reorganisation is also hers.",
          "dream_outcome": "The tool does the organising - search finds it whatever the tree looks like - so curation stops being a person's second job."
        }
      },
      "segments": ["seg:startup", "seg:enterprise"],
      "feature_ref": "feat:kb",
      "feature_note": "This is the pain feat:kb and feat:ai are both aimed at, so this row is the test of the company's own hypothesis rather than a confirmation of it. The test half-fails: Hamuko and koliber are describing Notion's own search degrading as their workspaces grow, not a competitor's. What the map does support is that the pain is worse elsewhere - more_corn prefers Notion to Confluence for writing and still cannot find a Confluence page six months later - which is the comparison the positioning step has to work with.",
      "cites": ["src:13", "src:15", "src:16", "src:17"]
    },
    {
      "id": "pain:docs-here-tickets-there",
      "statement": "Our docs are in one tool, our tickets are in another, and every new person starts a third.",
      "element": "b2b:ease_of_doing_business:integration",
      "shape": {
        "surface": "A single company runs Notion and Confluence and Google Docs at the same time, and no one of them is reliably where the answer is.",
        "operational": "Task tracking gets moved to a dedicated tool and the wiki is left behind, so now there are two systems and a standing open question about which one owns what.",
        "personal": "The same thankless curation job as the pain above, made worse: whoever keeps it straight now has to keep three platforms straight, and hnlmorg's conclusion is that it is easier to give up and accept the sprawl."
      },
      "workflow": "Looking for a decision or a spec at a 50-person company that runs Confluence, Notion and Google Docs at once - or one running Sharepoint, Notion and Confluence as official tools - at the step where you have to guess which of the three the writer picked, and then search all three.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "New people join and bring the tool they were productive in, which starts the next parallel wiki.",
          "cites": ["src:16"]
        },
        {
          "event": "The team grows past about five people, which is where sanedigital's company stopped finding Notion sufficient.",
          "cites": ["src:19"]
        }
      ],
      "who_feels": ["champion"],
      "by_role": {
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "One startup I worked for somehow managed to have stuff scattered between Confluence, Notion and Google Docs despite only employing 50 people. It was crazy.",
              "cites": ["src:16"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "my team is very happy we migrated from Notion to Linear for task tracking last year, but we're still looking how to cover the wiki part.",
              "cites": ["src:18"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Notion was great when we were <5 people, but it feels like a toy compared to Confluence.",
              "cites": ["src:19"]
            }
          ],
          "costs_them": "He solved half the problem and now carries the other half as an open search, with the team split across two tools while he looks; and if it goes the way sanedigital's company went, he carries a full migration as well.",
          "fears": "That he trades one tool for two and the wiki stays unsolved, which is exactly where alexey-salmin is, and that the flexible tool that suited five people will not hold fifty.",
          "dream_outcome": "One place where the tickets and the documents know about each other, so the migration ends rather than continuing, and the decision holds as the company grows."
        }
      },
      "segments": ["seg:startup", "seg:enterprise"],
      "feature_ref": "feat:projects",
      "feature_note": "Docs and Projects in one workspace is the company's answer to this, and it is the one pain in this map where a company hypothesis and the buyers' own words line up cleanly - alexey-salmin has literally split docs from tickets and wants them back together. The counter-evidence is sanedigital, whose company went the other way because Notion felt like a toy at scale; the positioning step needs an answer to that sentence. Note that every voice here is an internal advocate rather than a budget owner, which is why who_feels carries only champion; q:pains-enterprise-voice asks for the missing role.",
      "cites": ["src:16", "src:18", "src:19"]
    },
    {
      "id": "pain:accidental-seat-charge",
      "statement": "I shared a page with someone and it quietly turned my workspace into a paid annual plan, and I found out on my card statement.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Adding a person to a page adds them as a Member rather than a Guest, with no confirmation step naming a charge, and the workspace upgrades.",
        "operational": "They go back into settings, delete the people they added, open a support ticket, and argue about a refund window that started when the invoice was generated rather than when the money left.",
        "personal": "It is their own money and it is not small - over $100 in one case, over $830 in the other - and the refund was refused both times, so what is left is the charge plus the feeling of having been walked into it."
      },
      "workflow": "Clicking Share on a Notion page and typing an email address, at the step where the picker defaults to Member instead of Guest; then the credit card statement, weeks later, and the support ticket after that.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Sharing a page or document with someone outside the paid seats - the single ordinary action that sets the charge in motion.",
          "cites": ["src:34", "src:35"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I shared a document with family members on Notion and accidentally added them as Members instead of Guests. There was no friction, no confirmation step, nothing that hinted this would result in an annual paid seat. I only found out when I was charged over $100.",
              "cites": ["src:35"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "While simply trying to share content from my workspace, the platform's interface implicitly added users as \"Members\" instead of \"Guests\" and automatically upgraded my workspace to a high-tier Business Yearly plan.",
              "cites": ["src:34"]
            },
            {
              "situation": "venting",
              "verbatim": "I'm not surprised to find that many other users have fallen into the exact same trap. At some point, a pattern this consistent stops being an accident.",
              "cites": ["src:35"]
            }
          ],
          "costs_them": "A three-figure charge for a plan she does not want, plus the hours spent on a support thread that ended in a policy quotation.",
          "fears": "That the interface is built to do this on purpose, which is what Amber says out loud, and that clicking anything else in the product carries the same risk.",
          "dream_outcome": "The share dialog says, before the click, that this adds a paid seat and what it costs, and a mistake made in one click can be undone in one click."
        }
      },
      "segments": ["seg:individual", "seg:startup"],
      "feature_ref": null,
      "feature_note": "No feature in the company artifact touches this. What would kill it is a confirmation step in the share dialog that names the charge before it happens, and a refund window that starts when the money is taken. It is in this map because it is the company's own pain, not the market's: the positioning step will meet it as an objection and the offer step must not promise around it.",
      "cites": ["src:34", "src:35"]
    },
    {
      "id": "pain:ai-first-buries-the-basics",
      "statement": "I came for a wiki and every screen wanted to sell me an agent, so it took me a while to find the thing I actually came for.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "The website, the signup flow and the first open of the mobile app all lead with AI, and the docs, wiki and database features are somewhere behind that.",
        "operational": "New users hunt for the core product, take screenshots and ask an LLM how to do basic things in it, or abandon the install.",
        "personal": "It is time spent feeling stupid in your own trial: mike is paying and taking screenshots to ask Claude how to do simple tasks, and Calapso's conclusion after an install is don't bother."
      },
      "workflow": "The first ten minutes - notion.com, the signup flow, and the first open of the Android app - at the step where someone looking for docs, a wiki or a filterable table is shown agents instead and has to go looking for the menu.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "First install or first signup, which is where every one of these quotes happens; none of them is from a long-term user.",
          "cites": ["src:25", "src:37"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "it was super weird to see that stuff so prominently given my understanding of what the company was all about.",
              "cites": ["src:25"]
            },
            {
              "situation": "when_looking",
              "verbatim": "So I go check out Notion and their entire site is focused on AI.",
              "cites": ["src:25"]
            },
            {
              "situation": "when_looking",
              "verbatim": "I signed up and the entire signup flow is also focused on AI.",
              "cites": ["src:25"]
            }
          ],
          "costs_them": "Evaluation time spent locating the product rather than judging it, which is time that comes out of a trial with a clock on it.",
          "fears": "That the company has moved on from the thing he wants, so the wiki he is about to standardise on is now a side feature somebody may stop caring about.",
          "dream_outcome": "He can see, in the first thirty seconds, that the docs and database product he came for is still the product, and judge it on that."
        },
        "end_user": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "Just installed on my android and it went straight to AI. No visible menus nor anyway to navigate to get started.",
              "cites": ["src:37"]
            },
            {
              "situation": "venting",
              "verbatim": "Great product but extremely hard to use. Consistently requires screenshots / asking claude for new users to accomplish simple tasks.",
              "cites": ["src:40"]
            }
          ],
          "costs_them": "The whole first session, and in Calapso's case the product: he uninstalled the idea before finding the menu.",
          "fears": "That he is missing something obvious that everybody else can see, which is exactly how Calapso words it.",
          "dream_outcome": "He opens the app and the first screen shows him a page he can write on, with the AI available rather than in the way."
        }
      },
      "segments": ["seg:individual", "seg:startup"],
      "feature_ref": "feat:ai",
      "feature_note": "feat:ai is not missing here, it is the thing in the way. The feature is doing its job of being visible and the price is that the docs, wiki and database product the buyer came for is harder to reach in the first ten minutes. This is a placement finding rather than an argument against the feature, and the direct consequence for the angles step is that an AI-led hook is wrong for anyone at this stage - they have not found the product yet.",
      "cites": ["src:25", "src:37", "src:40"]
    },
    {
      "id": "pain:private-notes-to-a-model",
      "statement": "Everything the company writes is in there, and now I have to say where it goes once the AI touches it.",
      "element": "b2b:individual:reduced_anxiety",
      "shape": {
        "surface": "The buyer finds out from the small print, a Hacker News thread or a disclosed vulnerability that workspace content reaches a third-party model.",
        "operational": "An admin files a support request to turn Notion AI off across the tenant and waits days for it, because there is no switch; or the user exports and leaves the same day.",
        "personal": "It lands on whoever vouched for the tool. light_hue_1 is an ML researcher who uses LLMs all the time and still calls it pretty much the worst case scenario for his own notes - not an anti-AI position, just an unwillingness to be the person who signed it off."
      },
      "workflow": "The security review before a workspace is standardised across a company: reading Notion's terms and subprocessor list, and the step where disabling Notion AI for the tenant is a support request measured in days rather than a toggle in admin settings.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "A publicly disclosed vulnerability in Notion AI, which in January 2026 moved at least one user to migrate off the same day.",
          "cites": ["src:23", "src:24"]
        },
        {
          "event": "A security or legal review before the workspace is standardised, where the terms get read properly for the first time.",
          "cites": ["src:36"]
        }
      ],
      "who_feels": ["blocker", "technical_evaluator"],
      "by_role": {
        "blocker": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I don't want my private notes sent to places like openai who will use them to train models and who don't have any reasonable corporate governance.",
              "cites": ["src:21"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "I would be wary of trusting Notion with your sensitive data. They do not seem to be default on the side of their customers.",
              "cites": ["src:36"]
            }
          ],
          "costs_them": "The review itself, and then owning a decision whose downside is unbounded and whose upside belongs to someone else.",
          "fears": "That the disclosure is in the small print by design, which is Travis Potter's actual complaint, and that the default is set against him.",
          "dream_outcome": "The data path is stated plainly on the page where he can find it, and he can turn the whole thing off himself before he has to explain it to anyone."
        },
        "technical_evaluator": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "As much as I love using Notion, they have a terrible track record when it comes to dealing with and responding to security issues.",
              "cites": ["src:23"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "You can turn Notion AI off in your tenant. It takes a few days, but support will do it. It's annoying that we have to ask instead of toggling a switch, but there you go.",
              "cites": ["src:22"]
            }
          ],
          "costs_them": "Days of waiting on a support queue to apply a control he should be able to set himself, while the thing he is trying to disable stays on.",
          "fears": "That the response to the next disclosure looks like the last one, and that the control he asked for is a favour rather than a setting.",
          "dream_outcome": "A tenant-level switch in admin settings that takes effect immediately, and a vendor whose disclosure handling he can point at when asked."
        }
      },
      "segments": ["seg:startup", "seg:enterprise"],
      "feature_ref": "feat:ai",
      "feature_note": "The same feature as pain:ai-first-buries-the-basics, seen from the other side of the table: what makes it worth paying for to the champion is what the blocker has to sign off on. Nothing in the company artifact is a tenant-level control, and nunez shows the control exists only as a support request, which is the specific gap between the two roles.",
      "cites": ["src:21", "src:23", "src:36"]
    },
    {
      "id": "pain:no-way-to-know-if-its-still-true",
      "statement": "I'm reading a page from who knows when, and there's nothing on it that tells me whether anybody still stands behind it.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "The page carries a last-edited timestamp, which records when someone touched the text, not whether the content is still correct.",
        "operational": "They build their own signal: syncing notes to a git repository so changes can be diffed and reviewed, or skipping the page and asking the author in chat.",
        "personal": null,
        "personal_note": "Nobody read here says what it cost them to act on a page that was no longer true. The workaround is described in detail (a git repo they can diff) and so is the wish (a freshness stamp), but never the consequence. Read the whole Notion's mid-life crisis thread and the documentation-tooling Ask HN threads on Hacker News. q:pains-stale-page-cost asks the founder for the real one."
      },
      "workflow": "Opening an internal Notion or Confluence page during onboarding or just before a decision, at the step where the only signal in the page header is a last-edited date - and, in a workspace of tens of thousands of notes, no way to see whether it changed under you.",
      "type": "latent",
      "revealed_by": "feat:kb",
      "confidence": "medium",
      "triggers": [
        {
          "event": "The workspace passes the point where one person can hold in their head which pages are current; vunderba puts that at tens of thousands of notes.",
          "cites": ["src:20"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "When you have tens of thousands of notes, it's hard to even know if at some point, the note has been suddenly changed, reverted, or modified in a way that you didn't even realize occurred.",
              "cites": ["src:20"]
            },
            {
              "situation": "when_looking",
